}

using System.ComponentModel.DataAnnotations;

namespace TicketClassifier.Models;

public class TicketRequest
{
    [Required]
    public string Subject { get; set; } = string.Empty;

    [Required]
    public string Description { get; set; } = string.Empty;

    [Range(1, 3)]
    public int Priority { get; set; }
}

public class PredictionResponse
{
    public string PredictedCategory { get; set; } = string.Empty;
    public Dictionary<string, float> ConfidenceScores { get; set; } = new();
}

public class EvaluationResponse
{
    public double MacroAccuracy { get; set; }
    public double MicroAccuracy { get; set; }
    public double LogLoss { get; set; }
    public double LogLossReduction { get; set; }
    public PerClassMetrics[] PerClassMetrics { get; set; } = [];
}

public class PerClassMetrics
{
    public string ClassName { get; set; } = string.Empty;
    public double Precision { get; set; }
    public double Recall { get; set; }
    public double F1Score { get; set; }
}

using Microsoft.ML;
using TicketClassifier.Models;

namespace TicketClassifier.Services;

public class TicketClassifierService
{
    private readonly MLContext _mlContext;
    private readonly ITransformer _model;
    private readonly PredictionEngine<TicketData, TicketPrediction> _predictionEngine;
    private readonly string[] _classNames;
    private readonly EvaluationResponse _evaluationMetrics;

    public TicketClassifierService(string dataPath)
    {
        _mlContext = new MLContext(seed: 42);

        var dataView = _mlContext.Data.LoadFromTextFile<TicketData>(
            dataPath, hasHeader: true, separatorChar: ',', allowQuoting: true);

        var pipeline = _mlContext.Transforms.Conversion.MapValueToKey("Label")
            .Append(_mlContext.Transforms.Text.FeaturizeText("SubjectFeaturized", nameof(TicketData.Subject)))
            .Append(_mlContext.Transforms.Text.FeaturizeText("DescriptionFeaturized", nameof(TicketData.Description)))
            .Append(_mlContext.Transforms.Concatenate("Features",
                "SubjectFeaturized", "DescriptionFeaturized", nameof(TicketData.Priority)))
            .Append(_mlContext.Transforms.NormalizeMinMax("Features"))
            .AppendCacheCheckpoint(_mlContext)
            .Append(_mlContext.MulticlassClassification.Trainers.SdcaMaximumEntropy())
            .Append(_mlContext.Transforms.Conversion.MapKeyToValue("PredictedLabel"));

        _model = pipeline.Fit(dataView);
        _predictionEngine = _mlContext.Model.CreatePredictionEngine<TicketData, TicketPrediction>(_model);

        // Extract class names from the key-value mapping
        var labelColumn = dataView.Schema["Label"];
        var keyType = _model.GetOutputSchema(dataView.Schema)["PredictedLabel"];
        _classNames = ExtractClassNames(dataView);

        // Evaluate on training data (small dataset — no separate test set)
        _evaluationMetrics = Evaluate(dataView);
    }

    private string[] ExtractClassNames(IDataView dataView)
    {
        var transformedData = _model.Transform(dataView);
        var schema = transformedData.Schema;
        var scoreColumn = schema["Score"];

        var slotNames = new VBuffer<ReadOnlyMemory<char>>();
        scoreColumn.GetSlotNames(ref slotNames);

        return slotNames.DenseValues().Select(v => v.ToString()).ToArray();
    }

    public PredictionResponse Predict(TicketRequest request)
    {
        var ticketData = new TicketData
        {
            Subject = request.Subject,
            Description = request.Description,
            Priority = request.Priority
        };

        var prediction = _predictionEngine.Predict(ticketData);

        var confidenceScores = new Dictionary<string, float>();
        for (int i = 0; i < _classNames.Length; i++)
        {
            confidenceScores[_classNames[i]] = prediction.Score[i];
        }

        return new PredictionResponse
        {
            PredictedCategory = prediction.Category,
            ConfidenceScores = confidenceScores
        };
    }

    public EvaluationResponse GetMetrics() => _evaluationMetrics;

    private EvaluationResponse Evaluate(IDataView data)
    {
        var predictions = _model.Transform(data);
        var metrics = _mlContext.MulticlassClassification.Evaluate(predictions);

        var perClass = metrics.PerClassLogLoss
            .Select((_, i) => new PerClassMetrics
            {
                ClassName = i < _classNames.Length ? _classNames[i] : $"Class{i}",
                Precision = i < metrics.ConfusionMatrix.PerClassPrecision.Count
                    ? metrics.ConfusionMatrix.PerClassPrecision[i] : 0,
                Recall = i < metrics.ConfusionMatrix.PerClassRecall.Count
                    ? metrics.ConfusionMatrix.PerClassRecall[i] : 0,
                F1Score = CalculateF1(
                    i < metrics.ConfusionMatrix.PerClassPrecision.Count
                        ? metrics.ConfusionMatrix.PerClassPrecision[i] : 0,
                    i < metrics.ConfusionMatrix.PerClassRecall.Count
                        ? metrics.ConfusionMatrix.PerClassRecall[i] : 0)
            })
            .ToArray();

        return new EvaluationResponse
        {
            MacroAccuracy = metrics.MacroAccuracy,
            MicroAccuracy = metrics.MicroAccuracy,
            LogLoss = metrics.LogLoss,
            LogLossReduction = metrics.LogLossReduction,
            PerClassMetrics = perClass
        };
    }

    private static double CalculateF1(double precision, double recall) =>
        precision + recall == 0 ? 0 : 2 * (precision * recall) / (precision + recall);
}

